<?php
require_once __DIR__ . '/includes/bootstrap.php'; require_admin();
$pageTitle='Gestion des présences';
$date=$_GET['date']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$date=date('Y-m-d');$entityId=(int)($_GET['entity_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$attendanceId=(int)($_POST['attendance_id']??0);$newArrival=trim($_POST['heure_arrivee']??'');$newExit=trim($_POST['heure_sortie']??'');$reason=trim($_POST['motif']??'');
 if(!$attendanceId||!$reason){flash('danger','Un pointage et un motif de correction sont obligatoires.');}
 elseif(($newArrival!==''&&!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$newArrival))||($newExit!==''&&!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$newExit))||($newExit!==''&&$newArrival==='')){flash('danger','Heures invalides. Une sortie ne peut exister sans arrivée.');}
 else {try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT * FROM attendance WHERE id=? FOR UPDATE');$s->execute([$attendanceId]);$old=$s->fetch();if(!$old)throw new RuntimeException();$u=$pdo->prepare('UPDATE attendance SET heure_arrivee=?,heure_sortie=?,updated_at=NOW() WHERE id=?');$u->execute([$newArrival?:null,$newExit?:null,$attendanceId]);$a=$pdo->prepare('INSERT INTO audit_logs(admin_id,attendance_id,action,details) VALUES(?,?,?,?)');$a->execute([$_SESSION['admin_id'],$attendanceId,'correction',json_encode(['avant'=>$old,'apres'=>['heure_arrivee'=>$newArrival?:null,'heure_sortie'=>$newExit?:null],'motif'=>$reason],JSON_UNESCAPED_UNICODE)]);$pdo->commit();flash('success','Correction enregistrée et journalisée.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','La correction a échoué.');}}
 header('Location: attendance.php?date='.urlencode($date).'&entity_id='.$entityId);exit;
}
$entities=$pdo->query('SELECT id,nom FROM entities WHERE actif=1 ORDER BY id')->fetchAll();
$sql="SELECT a.id attendance_id,a.work_date,a.heure_arrivee,a.heure_sortie,e.matricule,e.nom,e.prenom,ent.nom entite FROM attendance a JOIN employees e ON e.id=a.employee_id JOIN entities ent ON ent.id=e.entity_id WHERE a.work_date=?";$params=[$date];if($entityId){$sql.=' AND e.entity_id=?';$params[]=$entityId;}$sql.=' ORDER BY ent.id,e.nom';$s=$pdo->prepare($sql);$s->execute($params);$rows=$s->fetchAll();
require __DIR__ . '/includes/header.php';
?>
<div class="mb-4"><div class="eyebrow">Contrôle et corrections</div><h1 class="h2 section-title">Présences enregistrées</h1><p class="small-muted">Les corrections exigent un motif et sont conservées dans le journal d’audit.</p></div>
<form class="panel mb-4" method="get"><div class="row g-3 align-items-end"><div class="col-sm-5"><label class="form-label">Date</label><input type="date" class="form-control" name="date" value="<?= e($date) ?>"></div><div class="col-sm-5"><label class="form-label">Entité</label><select class="form-select" name="entity_id"><option value="0">Toutes</option><?php foreach($entities as $ent): ?><option value="<?= $ent['id'] ?>" <?= $entityId===$ent['id']?'selected':'' ?>><?= e($ent['nom']) ?></option><?php endforeach; ?></select></div><div class="col-sm-2"><button class="btn btn-primary w-100">Filtrer</button></div></div></form>
<section class="panel"><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Matricule</th><th>Employé</th><th>Entité</th><th>Arrivée</th><th>Sortie</th><th>Correction</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td><?= e($r['matricule']) ?></td><td><?= e(trim($r['prenom'].' '.$r['nom'])) ?></td><td><?= e($r['entite']) ?></td><td><?= $r['heure_arrivee']?e(substr($r['heure_arrivee'],0,5)):'—' ?></td><td><?= $r['heure_sortie']?e(substr($r['heure_sortie'],0,5)):'—' ?></td><td><details><summary class="text-primary">Modifier</summary><form class="mt-2" method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="attendance_id" value="<?= $r['attendance_id'] ?>"><label class="form-label small">Arrivée</label><input type="time" class="form-control mb-2" name="heure_arrivee" value="<?= e($r['heure_arrivee']?substr($r['heure_arrivee'],0,5):'') ?>"><label class="form-label small">Sortie</label><input type="time" class="form-control mb-2" name="heure_sortie" value="<?= e($r['heure_sortie']?substr($r['heure_sortie'],0,5):'') ?>"><label class="form-label small">Motif obligatoire</label><input class="form-control mb-2" name="motif" required maxlength="500"><button class="btn btn-sm btn-primary" data-confirm="Confirmer la correction ?">Enregistrer</button></form></details></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="6" class="empty-state">Aucun pointage enregistré pour cette date et ce filtre.</td></tr><?php endif; ?>
</tbody></table></div><p class="small-muted mb-0">Pour les employés sans pointage, consultez le tableau de bord : une absence doit être vérifiée avant d’être confirmée.</p></section>
